#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef unsigned long long ull;

const int mod = 998244353;
const int NTTPrimes[] = {1053818881, 1051721729, 1045430273, 1012924417, 1007681537, 1004535809, 998244353, 985661441, 976224257, 975175681};
const int NTTPrimitiveRoots[] = {7, 6, 3, 5, 3, 3, 3, 3, 3, 17};

vector<ll> clean(const vector<ll>& a) {
    int i = (int)a.size() - 1;
    while (i >= 0 && a[i] == 0) --i;
    if (i < 0) return vector<ll>();
    if (i + 1 == (int)a.size()) return a;
    return vector<ll>(a.begin(), a.begin() + i + 1);
}

vector<ll> mulnaive(const vector<ll>& a, const vector<ll>& b) {
    int n = (int)a.size(), m = (int)b.size();
    vector<ll> c(n + m - 1, 0);
    ll big = 8LL * mod * mod;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            c[i + j] += a[i] * b[j];
            if (c[i + j] >= big) c[i + j] -= big;
        }
    }
    for (int i = 0; i < (int)c.size(); ++i) c[i] %= mod;
    return c;
}

ll pow_mod(ll a, ll n, ll P) {
    ll res = 1;
    while (n) {
        if (n & 1) res = res * a % P;
        a = a * a % P;
        n >>= 1;
    }
    return res;
}

ll invl(ll a, ll P) {
    ll b = P, p = 1, q = 0;
    while (b) {
        ll c = a / b;
        ll d = a; a = b; b = d % b;
        d = p; p = q; q = d - c * q;
    }
    return p < 0 ? p + P : p;
}

ll modh(ll a, ll M, int h, int P) {
    ll r = a - ((M * (a & ((1LL << 31) - 1)) >> 31) + M * (a >> 31) >> (h - 31)) * P;
    return r < P ? r : r - P;
}

vector<ll> nttmb(const vector<ll>& src, int n, bool inverse, int P, int g) {
    vector<ll> dst = src;
    dst.resize(n);
    int h = __builtin_ctz(n);
    ll K = (ll)(1ULL << 31) << 1; // faster to set K = 1LL << 32
    // Actually we need K = highestOneBit(P) * 2, but P < 2^31 so K = 2^32
    K = 1LL << 32;
    int H = 64 - __builtin_clzll(K) - 1; // trailing zeros of K? Actually H = number of trailing zeros in K = 32? Let's compute simpler: H = 64 - __builtin_clzll(K) = 64 - 32 = 32; but original Java uses H = Long.numberOfTrailingZeros(K)*2? That is 64? Let's follow Java exactly.
    // Java: long K = Integer.highestOneBit(P)<<1; int H = Long.numberOfTrailingZeros(K)*2;
    // For P=998244353, highestOneBit(P)=2^29 (since 2^29=536870912, 2^30=1073741824 > P), K=2^30, number of trailing zeros of 2^30 is 30, H=60.
    // But in the code, K=2^30, so trailing zeros = 30, H=60.
    // Let's compute properly:
    K = 1LL << (32 - __builtin_clz(P) - 1) << 1; // highestOneBit(P)<<1
    // Actually easier: K = 1LL << (32 - __builtin_clz(P));
    // Let's do:
    int hP = 31 - __builtin_clz(P); // floor(log2(P))
    K = 1LL << (hP + 1); // highestOneBit(P)*2
    int H = __builtin_ctzll(K) * 2; // trailing zeros * 2

    ll M = (K * K) / P; // K*K/P, careful with overflow? K up to 2^31, K*K up to 2^62, fits in unsigned long long.
    // Use unsigned long long for safety.
    ull M_ull = (ull)K * K / P;

    ll dw = inverse ? pow_mod(g, P - 1 - (P - 1) / n, P) : pow_mod(g, (P - 1) / n, P);
    vector<int> wws(1 << (h - 1));
    ll w = (1LL << 32) % P;
    for (int k = 0; k < (1 << (h - 1)); ++k) {
        wws[k] = (int)w;
        w = modh(w * dw, M_ull, H, P); // ensure modh works with ull? But modh expects M as long? We'll cast M.
    }
    ll J = invl(P, 1LL << 32);
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < (1 << i); ++j) {
            for (int k = 0, s = j << (h - i), t = s | (1 << (h - i - 1)); k < (1 << (h - i - 1)); ++k, ++s, ++t) {
                ll u = (dst[s] - dst[t] + 2 * P) * wws[k];
                dst[s] += dst[t];
                if (dst[s] >= 2 * P) dst[s] -= 2 * P;
                ll Q = ((ull)(u) << 32) * J >> 32;
                dst[t] = (u >> 32) - (Q * P >> 32) + P;
            }
        }
        if (i < h - 1) {
            for (int k = 0; k < (1 << (h - i - 2)); ++k) {
                wws[k] = wws[k * 2];
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        if (dst[i] >= P) dst[i] -= P;
    }
    // Bit-reversal permutation
    for (int i = 0; i < n; ++i) {
        int rev = __builtin_bitreverse32((unsigned)i) >> (32 - h);
        if (i < rev) swap(dst[i], dst[rev]);
    }
    if (inverse) {
        ll in = invl(n, P);
        for (int i = 0; i < n; ++i) dst[i] = modh(dst[i] * in, M_ull, H, P);
    }
    return dst;
}

vector<ll> convoluteSimply(const vector<ll>& a, const vector<ll>& b, int P, int g) {
    int m = max(2, 1 << (32 - __builtin_clz(max((int)a.size(), (int)b.size()) - 1) + 1));
    vector<ll> fa = nttmb(a, m, false, P, g);
    vector<ll> fb = (a == b) ? fa : nttmb(b, m, false, P, g);
    for (int i = 0; i < m; ++i) fa[i] = fa[i] * fb[i] % P;
    return nttmb(fa, m, true, P, g);
}

